insert into public.categories (key, group_key, name, summary, final_keys, availability, needs, steps, dos, donts, confused_with, sort) values ('live_person', 'real', 'Live person', 'Just you, live, in front of the camera.', array['real']::text[], 'everyone', '["Good lighting"]'::jsonb, '["Hold the phone at arm''s length with your face in the oval.","Look at the camera and blink naturally.","Stay in frame for the whole recording."]'::jsonb, '["Try different rooms and lighting","Glasses on or off is fine"]'::jsonb, '["No beauty filters","Don''t cover your face"]'::jsonb, array[]::text[], 1) on conflict (key) do update set group_key = excluded.group_key, name = excluded.name, summary = excluded.summary, final_keys = excluded.final_keys, availability = excluded.availability, needs = excluded.needs, steps = excluded.steps, dos = excluded.dos, donts = excluded.donts, confused_with = excluded.confused_with, sort = excluded.sort;
insert into public.categories (key, group_key, name, summary, final_keys, availability, needs, steps, dos, donts, confused_with, sort) values ('printed_photo', 'printed', 'Printed photo', 'A flat printed photo of a face, held up to the camera.', array['print', 'mask_2d']::text[], 'needs_props', '["A printed photo of a face (paper)"]'::jsonb, '["Hold the printout in front of the camera.","Fill the oval with the face in the photo.","Tilt it slightly and keep it steady."]'::jsonb, '["Use a clear, well-printed photo","Keep the photo flat"]'::jsonb, '["Don''t bend the paper","Don''t show a photo on a screen (that''s a different card)"]'::jsonb, array['cutout_mask', 'curved_photo']::text[], 2) on conflict (key) do update set group_key = excluded.group_key, name = excluded.name, summary = excluded.summary, final_keys = excluded.final_keys, availability = excluded.availability, needs = excluded.needs, steps = excluded.steps, dos = excluded.dos, donts = excluded.donts, confused_with = excluded.confused_with, sort = excluded.sort;
insert into public.categories (key, group_key, name, summary, final_keys, availability, needs, steps, dos, donts, confused_with, sort) values ('cutout_mask', 'printed', 'Photo cut-out mask', 'A printed face cut out and worn like a mask.', array['paper_mask']::text[], 'needs_props', '["A printed face photo","Scissors"]'::jsonb, '["Cut out the printed face. Eye holes are optional.","Wear or hold it over your face.","Look at the camera and move slightly."]'::jsonb, '["Make the cut-out cover your whole face"]'::jsonb, '["Don''t just hold a flat photo (that''s Printed photo)"]'::jsonb, array['printed_photo', 'cardboard_3d']::text[], 3) on conflict (key) do update set group_key = excluded.group_key, name = excluded.name, summary = excluded.summary, final_keys = excluded.final_keys, availability = excluded.availability, needs = excluded.needs, steps = excluded.steps, dos = excluded.dos, donts = excluded.donts, confused_with = excluded.confused_with, sort = excluded.sort;
insert into public.categories (key, group_key, name, summary, final_keys, availability, needs, steps, dos, donts, confused_with, sort) values ('curved_photo', 'printed', 'Curved printed photo', 'A printed face photo bent around a bottle, cylinder or head-shaped object.', array['mask_cylinder', 'wrapped']::text[], 'needs_props', '["A printed face photo","A bottle, cylinder or similar object"]'::jsonb, '["Wrap the photo around the object.","Hold it up so the face looks toward the camera.","Turn it slowly left and right."]'::jsonb, '["Keep the face visible and centered"]'::jsonb, '["Don''t leave the photo flat"]'::jsonb, array['printed_photo']::text[], 4) on conflict (key) do update set group_key = excluded.group_key, name = excluded.name, summary = excluded.summary, final_keys = excluded.final_keys, availability = excluded.availability, needs = excluded.needs, steps = excluded.steps, dos = excluded.dos, donts = excluded.donts, confused_with = excluded.confused_with, sort = excluded.sort;
insert into public.categories (key, group_key, name, summary, final_keys, availability, needs, steps, dos, donts, confused_with, sort) values ('replay_phone', 'screen', 'Phone screen', 'A video or photo of a face shown on a phone screen.', array['replay_phone']::text[], 'needs_props', '["A second phone","A video or photo of a face"]'::jsonb, '["Play the face video on the second phone at full brightness.","Hold it in front of the camera so the face fills the oval.","Keep both phones steady."]'::jsonb, '["Turn screen brightness up"]'::jsonb, '["Don''t cover the screen with your hand"]'::jsonb, array['replay_monitor']::text[], 5) on conflict (key) do update set group_key = excluded.group_key, name = excluded.name, summary = excluded.summary, final_keys = excluded.final_keys, availability = excluded.availability, needs = excluded.needs, steps = excluded.steps, dos = excluded.dos, donts = excluded.donts, confused_with = excluded.confused_with, sort = excluded.sort;
insert into public.categories (key, group_key, name, summary, final_keys, availability, needs, steps, dos, donts, confused_with, sort) values ('replay_monitor', 'screen', 'Computer screen', 'A face shown on a laptop or desktop monitor.', array['replay_monitor']::text[], 'needs_props', '["A laptop or monitor","A video or photo of a face"]'::jsonb, '["Show the face full-screen on the computer.","Point the camera at the screen from about arm''s length.","Avoid glare and keep steady."]'::jsonb, '["Fill the oval with the face on screen"]'::jsonb, '["Don''t show yourself live on the screen"]'::jsonb, array['replay_phone']::text[], 6) on conflict (key) do update set group_key = excluded.group_key, name = excluded.name, summary = excluded.summary, final_keys = excluded.final_keys, availability = excluded.availability, needs = excluded.needs, steps = excluded.steps, dos = excluded.dos, donts = excluded.donts, confused_with = excluded.confused_with, sort = excluded.sort;
insert into public.categories (key, group_key, name, summary, final_keys, availability, needs, steps, dos, donts, confused_with, sort) values ('cardboard_3d', 'mask', '3D cardboard mask', 'A 3D face mask built from connected cardboard pieces.', array['mask_3d']::text[], 'needs_props', '["Cardboard pieces with face prints","Tape or glue"]'::jsonb, '["Assemble the pieces into a face-shaped 3D mask.","Wear it or hold it in front of your face.","Look at the camera and turn slightly."]'::jsonb, '["Make sure the face is recognisable"]'::jsonb, '["Don''t use a single flat piece (that''s Photo cut-out mask)"]'::jsonb, array['cutout_mask']::text[], 7) on conflict (key) do update set group_key = excluded.group_key, name = excluded.name, summary = excluded.summary, final_keys = excluded.final_keys, availability = excluded.availability, needs = excluded.needs, steps = excluded.steps, dos = excluded.dos, donts = excluded.donts, confused_with = excluded.confused_with, sort = excluded.sort;
insert into public.categories (key, group_key, name, summary, final_keys, availability, needs, steps, dos, donts, confused_with, sort) values ('latex_mask', 'mask', 'Latex mask', 'A stretchy rubber mask shaped like a face.', array['latex_mask']::text[], 'special', '["A latex face mask"]'::jsonb, '["Put the mask on.","Look at the camera and move your head slightly.","Keep the mask in place for the whole recording."]'::jsonb, '["Use good, even lighting"]'::jsonb, '["Don''t use a mask that only covers the eyes"]'::jsonb, array['silicone_mask']::text[], 8) on conflict (key) do update set group_key = excluded.group_key, name = excluded.name, summary = excluded.summary, final_keys = excluded.final_keys, availability = excluded.availability, needs = excluded.needs, steps = excluded.steps, dos = excluded.dos, donts = excluded.donts, confused_with = excluded.confused_with, sort = excluded.sort;
insert into public.categories (key, group_key, name, summary, final_keys, availability, needs, steps, dos, donts, confused_with, sort) values ('silicone_mask', 'mask', 'Silicone mask', 'A very realistic, skin-like mask.', array['silicon_mask']::text[], 'special', '["A silicone face mask"]'::jsonb, '["Put the mask on.","Look at the camera and move your head slightly.","Keep the mask in place for the whole recording."]'::jsonb, '["Use good, even lighting"]'::jsonb, '["Don''t use a rubber party mask (that''s Latex mask)"]'::jsonb, array['latex_mask']::text[], 9) on conflict (key) do update set group_key = excluded.group_key, name = excluded.name, summary = excluded.summary, final_keys = excluded.final_keys, availability = excluded.availability, needs = excluded.needs, steps = excluded.steps, dos = excluded.dos, donts = excluded.donts, confused_with = excluded.confused_with, sort = excluded.sort;
